// A copy of scripts/masking-patterns.json, pinned by its SHA-256 (AR-15). `ci`
// (scripts/check_masking_hash.py) fails when the file changes without this
// copy; the next node re-hashes the copy on every run and W1 refuses to start
// anything when it doesn't match.
const MASKING_PATTERNS_SHA256 = '0521d2bbd3d976700a050807dc28de89f9f34fc88ff29b0b07505a16014ab222';
const MASKING_PATTERNS_RAW = "{
  "schema_version": 1,
  "_about": "The one set of masking patterns (AD-13, SEC-05). Applied in this order by scripts/sanitize.py (Python) and by the copy pinned in n8n W1 (JavaScript), so patterns use only regex syntax both understand: no named groups, no lookbehind, no backreferences in replacements. flags may be 'i'. Every pattern needs examples (text that must be masked); keeps lists text that must survive. Changing this file changes its hash: update the n8n copy in the same PR (scripts/check_masking_hash.py).",
  "patterns": [
    {
      "name": "private-key",
      "pattern": "-----BEGIN [A-Z ]*PRIVATE KEY-----[\\s\\S]*?-----END [A-Z ]*PRIVATE KEY-----",
      "flags": "",
      "replacement": "[private key]",
      "examples": ["-----BEGIN RSA PRIVATE KEY-----\nMIIEpAIBAAKCAQEAfake\n-----END RSA PRIVATE KEY-----"]
    },
    {
      "name": "jwt",
      "pattern": "\\beyJ[\\w-]{10,}\\.[\\w-]{10,}\\.[\\w-]{10,}",
      "flags": "",
      "replacement": "[token]",
      "examples": ["eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxMjM0NTY3ODkwIn0.dozjgNryP4J3jVmNHl0w5N_XgL0n3I9PlFUP0THsR8U"]
    },
    {
      "name": "known-token",
      "pattern": "\\b(?:xox[abposr]-[\\w-]{10,}|gh[pousr]_\\w{20,}|github_pat_\\w{20,}|sk-[\\w-]{20,}|[spr]k_(?:live|test)_\\w{10,}|AKIA[0-9A-Z]{16}|AIza[\\w-]{35})",
      "flags": "",
      "replacement": "[token]",
      "examples": [
        "xoxb-123456789012-abcdefghijkl",
        "ghp_aBcDeFgHiJkLmNoPqRsTuVwXyZ012345",
        "github_pat_11ABCDEFG0123456789_abcdefghij",
        "sk_live_51HfakeFAKEfake",
        "AKIAIOSFODNN7EXAMPLE",
        "sk-ant-api03-FAKEfakeFAKEfake12345"
      ]
    },
    {
      "name": "auth-header",
      "pattern": "\\b(?:bearer|basic|token)\\s+[\\w.~+/=-]{8,}",
      "flags": "i",
      "replacement": "[auth hidden]",
      "examples": ["Authorization: Bearer abc.def-ghi_jkl", "Authorization: Basic dXNlcjpwYXNzd29yZA=="],
      "keeps": ["the token was refused"]
    },
    {
      "name": "secret-value",
      "pattern": "\\b(?:password|passwd|pwd|secret|client[_-]?secret|api[_-]?key|access[_-]?token|refresh[_-]?token|token|otp)\\b[\"']?\\s*[=:]\\s*[\"']?[^\\s\"',;&)}\\[]+",
      "flags": "i",
      "replacement": "[secret hidden]",
      "examples": ["password=Hunter2!", "{\"api_key\": \"abc123def\"}", "?access_token=zzz999&page=2", "OTP: 482913"],
      "keeps": ["password field is empty", "test_reset_password_link", "token = \"[auth hidden]\""]
    },
    {
      "name": "url-credentials",
      "pattern": "//[^/\\s:@]+:[^/\\s@]+@",
      "flags": "",
      "replacement": "//[hidden]@",
      "examples": ["mysql://qa_readonly:s3cret@db.internal:3306/poolbrain"]
    },
    {
      "name": "email",
      "pattern": "[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}",
      "flags": "",
      "replacement": "[email]",
      "examples": ["jane.doe+pool@example.com", "Expected owner@acme-pools.co.uk to be shown"]
    },
    {
      "name": "street-address",
      "pattern": "\\b\\d{1,6}\\s+(?:[A-Z][A-Za-z]*\\.?\\s+){1,4}(?:Street|St|Avenue|Ave|Road|Rd|Boulevard|Blvd|Lane|Ln|Drive|Dr|Court|Ct|Way|Place|Pl|Terrace|Ter|Circle|Cir|Parkway|Pkwy|Highway|Hwy|Trail|Trl)\\b\\.?",
      "flags": "",
      "replacement": "[address]",
      "examples": ["1234 Palm Beach Blvd", "Service at 77 N. Ocean Dr. today", "5 Elm St"],
      "keeps": ["Expected 3 Jobs but found 2", "line 120 Step"]
    },
    {
      "name": "card-like-number",
      "pattern": "\\b(?:\\d[ -]?){12,18}\\d\\b",
      "flags": "",
      "replacement": "[card number]",
      "examples": ["4242 4242 4242 4242", "4111-1111-1111-1111", "5555555555554444"],
      "keeps": ["expected 200 but got 500", "job 104233 not found"]
    },
    {
      "name": "phone-number",
      "pattern": "(?:\\+?1[ .-]?)?\\(?\\b\\d{3}\\)?[ .-]\\d{3}[ .-]\\d{4}\\b",
      "flags": "",
      "replacement": "[phone]",
      "examples": ["(561) 555-0142", "+1 561-555-0142", "561.555.0142"],
      "keeps": ["at line 123"]
    },
    {
      "name": "long-hex-secret",
      "pattern": "\\b[A-Fa-f0-9]{32,}\\b",
      "flags": "",
      "replacement": "[hidden]",
      "examples": ["session 9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08"],
      "keeps": ["commit 5b4a364"]
    }
  ]
}
";
return [{ json: { raw: MASKING_PATTERNS_RAW, pinned: MASKING_PATTERNS_SHA256 } }];

// Never start anything with masking patterns that aren't the pinned ones.
const { pinned } = $('Masking patterns').first().json;
const actual = $input.first().json.actual;
if (actual !== pinned) {
  throw new Error(`Masking patterns copy does not match its pinned hash (${String(actual).slice(0, 12)}… vs ${pinned.slice(0, 12)}…); nothing was started`);
}
return [{ json: { ok: true } }];

// Tickets that newly moved to a watched status and have no record yet.
// "In Progress" (this board has no "Ready for Dev") starts draft-cases;
// "Ready to Test" starts generate-tests. Other statuses and projects are ignored.
const known = new Set($('Known requests').first().json.known ?? []);
const queued = new Set((Array.isArray($('Due queue').first().json.due) ? $('Due queue').first().json.due : [])
  .map((d) => `${d.ticket} ${d.workflow}`));
const found = [
  ...$('Find draft tickets').all().flatMap((p) => (p.json.issues ?? []).map((i) => ({ ticket: i.key, workflow: 'draft-cases' }))),
  ...$('Find test tickets').all().flatMap((p) => (p.json.issues ?? []).map((i) => ({ ticket: i.key, workflow: 'generate-tests' }))),
];
const seen = new Set();
return found
  .filter((r) => /^[A-Z][A-Z0-9]+-[0-9]+$/.test(r.ticket))
  .filter((r) => !known.has(`${r.ticket} ${r.workflow}`) && !queued.has(`${r.ticket} ${r.workflow}`))
  .filter((r) => !seen.has(`${r.ticket} ${r.workflow}`) && seen.add(`${r.ticket} ${r.workflow}`))
  .map((r) => ({ json: r }));

// Only the description and the acceptance criteria are read (SEC-05), turned
// from Jira's document format into plain text and masked with the pinned
// patterns. Nothing else from the ticket leaves Jira.
const MAX = 15000;
const patterns = JSON.parse($('Masking patterns').first().json.raw).patterns;
const mask = (text) => patterns.reduce((t, p) => t.replace(new RegExp(p.pattern, 'g' + (p.flags || '')), () => p.replacement), text);
const acField = $('Settings').first().json.ac_field;

// Atlassian Document Format to plain text: paragraphs and headings on their
// own lines, list items as "- ", tables cell by cell. Links keep their text only.
function plain(node, depth = 0) {
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (node.type === 'text') return node.text ?? '';
  if (node.type === 'hardBreak') return '\n';
  if (['mention', 'emoji', 'inlineCard'].includes(node.type)) return node.attrs?.text ?? '';
  const inner = (node.content ?? []).map((c) => plain(c, depth + 1)).join('');
  if (node.type === 'listItem') return `- ${inner.trim()}\n`;
  if (['paragraph', 'heading', 'codeBlock', 'blockquote', 'tableRow'].includes(node.type)) return `${inner.trim()}\n`;
  if (node.type === 'tableCell' || node.type === 'tableHeader') return `${inner.trim()} | `;
  return inner;
}

const requests = $('New requests').all();
return $input.all().map((item, i) => {
  const fields = item.json.fields ?? {};
  const description = plain(fields.description).trim();
  const criteria = plain(fields[acField]).trim();
  let text = `Description:\n${description || '(none)'}\n\nAcceptance criteria:\n${criteria || '(none)'}`;
  text = mask(text.replace(/\n{3,}/g, '\n\n'));
  if (text.length > MAX) text = `${text.slice(0, MAX - 1)}…`;
  return { json: { ...requests[i].json, ticket_text: text, queue_id: 0 } };
});

// Everything to put through the gate this run: newly found tickets (masked
// above) and due requests from the waiting list, which were masked when queued.
const fresh = $('Ticket text').isExecuted ? $('Ticket text').all().map((i) => i.json) : [];
const dueRaw = $('Due queue').first().json.due;
const due = (Array.isArray(dueRaw) ? dueRaw : JSON.parse(dueRaw || '[]'))
  .filter((d) => /^[A-Z][A-Z0-9]+-[0-9]+$/.test(d.ticket ?? ''));
return [...due, ...fresh].map((r) => ({
  json: {
    action: 'dispatch',
    workflow: r.workflow,
    target: r.ticket,
    payload: { ticket: r.ticket, ticket_text: r.ticket_text ?? '' },
    queue_id: r.queue_id ?? 0,
  },
}));

// Pair each gate answer with its request (both in the same order).
const requests = $('Requests to try').all();
return $input.all().map((answer, i) => ({ json: { ...requests[i].json, allowed: answer.json.allowed === true,
  reason: answer.json.reason ?? '' } }));

// One audit entry per start (a kept-back request is recorded by the gate).
const requests = $('Gate answers').all().filter((r) => r.json.allowed);
return requests.map((r) => ({
  json: {
    actor: 'n8n:w1-ticket-watcher',
    actor_type: 'n8n',
    action: `dispatch-${r.json.workflow}`,
    target: r.json.target,
    link: `https://github.com/${$('Settings').first().json.repo}/actions/workflows/${r.json.workflow}.yml`,
  },
}));

